"""Short plain-language explanations and runnable warm-ups for each main lesson."""
from copy import deepcopy
import ast

def line_notes(code):
    nodes={n.lineno:n for n in ast.walk(ast.parse(code)) if isinstance(n,ast.stmt) and hasattr(n,'lineno')}
    result=[]
    for number,line in enumerate(code.splitlines(),1):
        s=line.strip();n=nodes.get(number)
        if not s or s.startswith('#'):continue
        if isinstance(n,(ast.Import,ast.ImportFrom)):text='Подключить готовые инструменты стандартной библиотеки. Их имена доступны ниже.'
        elif isinstance(n,ast.FunctionDef):text=f'Описать функцию {n.name}. Её тело запустится при вызове, а не при объявлении.'
        elif isinstance(n,ast.For):text=f'По очереди брать значения из {ast.unparse(n.iter)} в {ast.unparse(n.target)}. Для каждого выполнить блок с отступом.'
        elif isinstance(n,ast.While):text=f'Повторять вложенный блок, пока условие {ast.unparse(n.test)} истинно.'
        elif isinstance(n,ast.If):text=f'Проверить {ast.unparse(n.test)}. При True выполнить следующий блок с отступом.'
        elif isinstance(n,ast.Return):text='Завершить этот вызов функции'+(f' и вернуть {ast.unparse(n.value)}.' if n.value else '.')
        elif isinstance(n,ast.Assign):
            names=', '.join(ast.unparse(t) for t in n.targets)
            text=f'Сначала вычислить правую часть, затем сохранить результат в {names}.'
            if 'input()' in ast.unparse(n.value):text=f'Прочитать данные из поля ввода, преобразовать их указанным способом и сохранить в {names}.'
        elif isinstance(n,ast.AugAssign):text=f'Обновить {ast.unparse(n.target)}, используя прежнее значение и {ast.unparse(n.value)}.'
        elif isinstance(n,ast.Expr) and isinstance(n.value,ast.Call):
            call=ast.unparse(n.value.func)
            text='Вывести указанные значения. Они будут сравнены с ожидаемым ответом.' if call=='print' else f'Выполнить действие {call} с указанными аргументами.'
        elif isinstance(n,ast.Break):text='Остановить ближайший цикл: продолжать перебор не нужно.'
        elif isinstance(n,ast.Continue):text='Пропустить оставшиеся строки этой итерации и перейти к следующей.'
        elif s=='else:':text='Выполнить этот блок, если предыдущая проверка не сработала.'
        else:text='Продолжение выражения или блока выше. Отступ показывает, к какому блоку относится строка.'
        result.append({'line':number,'code':line,'text':text})
    return result

