def expand_beginner(lessons):
    originals=[l for l in lessons if l['day']]
    assert {l['id'] for l in originals} == set(GUIDES) == set(DRILLS)
    warmups=[]
    for lesson in originals:
        ident=lesson['id'];why,analogy,recognition,steps,terms=GUIDES[ident]
        lesson['beginner']={'why':why,'analogy':analogy,'recognition':recognition,'steps':steps,'terms':terms}
        lesson['warmup']='warmup-'+ident
        title,task,starter,solution,expected,explain=DRILLS[ident]
        warmups.append(dict(id='warmup-'+ident,parent=ident,title=title,topic=lesson['topic'],day=0,level='Разминка',minutes=3,
            theory=['Здесь всего одно действие. Данные уже записаны в программе: поле ввода можно оставить пустым.',why],
            example='# Прочитай условие во вкладке «Решить».\n# Добавь недостающие строки в редакторе.',
            task=task,inputs='Вводить ничего не нужно: маленький пример уже записан в коде.',output=expected,
            starter=starter,solution=solution,hints=explain,explain=explain,
            complexity='В этой разминке фиксированный маленький пример; разберись в действии, а оценку общего алгоритма смотри в основном уроке.',
            trap=lesson['trap'],quiz=deepcopy(lesson['quiz']),tests=[{'input':'','expected':expected,'label':'Короткая разминка'}]))
    for lesson in lessons:
        if lesson.get('related'):
            lesson['beginner']=deepcopy(next(x for x in originals if x['id']==lesson['related'])['beginner'])
    lessons.extend(warmups)
    for lesson in lessons:lesson['lineNotes']=line_notes(lesson['solution'])
